import sys
import math

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    m = n // 2
    given = []
    idx = 1
    for _ in range(m):
        given.append(int(input_data[idx]))
        idx += 1

    current_sum = 0
    result = []

    for val in given:
        target_sum = current_sum + val
        found = False

        root = int(math.isqrt(target_sum))

        if root * root == target_sum:
            diff = 0
            prev_root = 0
            if current_sum > 0:
                prev_root = int(math.isqrt(current_sum))

            while True:
                next_root = prev_root + 1
                next_sq = next_root * next_root

                if next_sq < target_sum:
                    prev_root = next_root
                    continue

                if next_sq == target_sum:
                    diff = 0
                    break

                needed = next_sq - target_sum
                if needed > 0:
                    if needed < current_sum:
                        result.append(needed)
                        current_sum = next_sq
                        found = True
                        break
                    else:
                        prev_root = next_root
                        continue
                else:
                    break

            if not found:
                if root * root == target_sum:
                    result.append(0)
                    current_sum = target_sum
                    found = True

            if not found:
                print("No")
                return
        else:
            prev_root = 0
            if current_sum > 0 and current_sum != 0:
                prev_root = int(math.isqrt(current_sum)) + 1

            while True:
                next_root = prev_root
                next_sq = next_root * next_root

                if next_sq <= target_sum:
                    prev_root += 1
                    continue

                needed = next_sq - target_sum
                if needed < current_sum:
                    result.append(needed)
                    current_sum = next_sq
                    found = True
                    break
                else:
                    prev_root += 1

                if next_sq - target_sum >= current_sum:
                    if next_sq - current_sum > 10**18:
                        break

            if not found:
                print("No")
                return

        result.append(val)

    print("Yes")
    print(*(result))

if __name__ == "__main__":
    solve()
